-- Carga dos formulários Coleta MIR - TEDs e Coleta MIR - Convênios (com_edital).
-- Baseado nos documentos "2026.09.30 Coleta MIR TEDs - Versão final.pdf" e
-- "2026.09.30 Coleta MIR Convênios - Proposta.pdf".
--
-- Cria três editais do tipo 'formulario' por instrumento, conforme o perfil de preenchimento:
--   * (MIR): identificação, responsáveis, enquadramento, modalidade e fiscalização - servidor do MIR;
--   * (gestor / convenente): execução e projetos - aberto pelo instrumento em "Meus instrumentos", entre os da
--     UG (TED) ou do CNPJ (convênio) liberados para a pessoa pelo MIR (solicitação de acesso);
--   * (execução): atividades e beneficiários, um preenchimento por atividade, aberto pelo
--     projeto em "Meus instrumentos" (responsável vinculado pelo CPF). Ligado ao anterior por co_edital_adesao.
-- Cada bloco vira um agrupamento (aba) com suas perguntas. As dependências entre perguntas (depende_de) usam os
-- ids gerados nesta mesma execução. Prefixo de tabelas: joom_
--
-- Rodar uma única vez: cada execução cria novos registros.

SET NAMES utf8mb4;
START TRANSACTION;

-- ======================================================================
-- Coleta MIR - TEDs (MIR)
-- ======================================================================
INSERT INTO `joom_tb_edital` (`state`, `ordering`, `created_by`, `modified_by`, `no_edital`, `ds_edital`, `dt_abertura`, `dt_encerramento`, `dt_publicacao`, `tp_edital`, `co_edital_adesao`, `co_grupos`)
VALUES (1, 0, 0, 0, 'Coleta MIR - TEDs (MIR)', '<p>Instrumento para coleta de dados de forma territorializada dos Termos de Execução Descentralizada (TEDs) celebrados pelo Ministério da Igualdade Racial (MIR).</p><p><strong>Perfis de preenchimento:</strong></p><ul><li><strong>Identificação, responsáveis, enquadramento, modalidade de resposta e fiscalização:</strong> servidor do MIR</li><li><strong>Execução e projetos:</strong> gestor do TED na Unidade Descentralizada (atualização periódica), em formulário próprio (gestor), a partir do instrumento em "Meus instrumentos", com o acesso da sua UG liberado pelo MIR</li><li><strong>Atividades e beneficiários:</strong> responsável por cada projeto, identificado pelo CPF na lista de projetos do gestor do TED, em formulário próprio (execução), um preenchimento por atividade</li></ul><p>A sugestão de periodicidade de atualização é trimestral.</p><p>Campos marcados como automáticos serão preenchidos a partir do Transferegov.br / SIAFI / Siorg quando a integração estiver disponível; até lá, preencha manualmente.</p>', '2026-11-01 00:00:00', '2027-12-31 23:59:59', '2026-11-01 00:00:00', 'formulario', NULL, (SELECT GROUP_CONCAT(`id` ORDER BY `id`) FROM `joom_usergroups` WHERE `title` IN ('Gerenciar Adesões')));
SET @ted_edital = LAST_INSERT_ID();

