VALUES (1, 4, 0, 0, 'Objetivos Específicos', @ted_edital, 'Obrigatório quando houver Programa do PPA selecionado.', 'lista', '{"ds_opcoes0": {"nome": "0264 - Criar mecanismos de identificação e de enfrentamento à violência e à discriminação contra quilombolas, povos e comunidades tradicionais de matriz africana, povos de terreiros e ciganos", "valor": "0264 - Criar mecanismos de identificação e de enfrentamento à violência e à discriminação contra quilombolas, povos e comunidades tradicionais de matriz africana, povos de terreiros e ciganos"}, "ds_opcoes1": {"nome": "0323 - Fomentar ações que fortaleçam as práticas agroecológicas, o fornecimento energético, o saneamento, a soberania alimentar, a valorização cultural, social, os saberes e fazeres dos quilombolas, povos e comunidades tradicionais de matriz africana, povos de terreiros e ciganos", "valor": "0323 - Fomentar ações que fortaleçam as práticas agroecológicas, o fornecimento energético, o saneamento, a soberania alimentar, a valorização cultural, social, os saberes e fazeres dos quilombolas, povos e comunidades tradicionais de matriz africana, povos de terreiros e ciganos"}, "ds_opcoes2": {"nome": "fonte_dw", "valor": "ppa_objetivos_especificos"}}', 'sim', 5, @ted_g_b3, 'adesao', @ted_p_ppa, '["5802 - Políticas para Quilombolas, Comunidades Tradicionais de Matriz Africana, Povos de Terreiros e Povos Ciganos", "5803 - Juventude Negra Viva", "5804 - Promoção da Igualdade Étnico-Racial, Combate e Superação do Racismo"]');
