VALUES (1, 9, 0, 0, 'ODS 18 - Igualdade Étnico-Racial (meta específica)', @ted_edital, 'Orientação: consulte as metas nacionais do ODS 18 na Portaria Conjunta MPI/MIR/SG-PR nº 198, de 24/09/2025.', 'lista', '{"ds_opcoes0": {"nome": "18.1. Eliminar o racismo e a discriminação", "valor": "18.1. Eliminar o racismo e a discriminação"}, "ds_opcoes1": {"nome": "18.2. Eliminar violências", "valor": "18.2. Eliminar violências"}, "ds_opcoes2": {"nome": "18.3. Garantir tratamento justo", "valor": "18.3. Garantir tratamento justo"}, "ds_opcoes3": {"nome": "18.4. Representatividade", "valor": "18.4. Representatividade"}, "ds_opcoes4": {"nome": "18.5. Promover a reparação", "valor": "18.5. Promover a reparação"}, "ds_opcoes5": {"nome": "18.6. Assegurar moradias adequadas", "valor": "18.6. Assegurar moradias adequadas"}, "ds_opcoes6": {"nome": "18.7. Assegurar à saúde", "valor": "18.7. Assegurar à saúde"}, "ds_opcoes7": {"nome": "18.8. Assegurar educação de qualidade", "valor": "18.8. Assegurar educação de qualidade"}, "ds_opcoes8": {"nome": "18.9. Promover o reconhecimento dos saberes", "valor": "18.9. Promover o reconhecimento dos saberes"}, "ds_opcoes9": {"nome": "18.10. Eliminar a xenofobia", "valor": "18.10. Eliminar a xenofobia"}}', 'nao', 5, @ted_g_b3, 'adesao', @ted_p_ods, '["18. Promoção da Igualdade Étnico-Racial"]');
