VALUES (1, 11, 0, 0, 'Áreas do MIR', @ted_edital, 'Por extenso, conforme Decreto nº 11.346/2023.', 'checkbox', '{"ds_opcoes0": {"nome": "Diretoria de Políticas de Ações Afirmativas (DPA)", "valor": "Diretoria de Políticas de Ações Afirmativas (DPA)"}, "ds_opcoes1": {"nome": "Diretoria de Políticas de Combate e Superação do Racismo (DCR)", "valor": "Diretoria de Políticas de Combate e Superação do Racismo (DCR)"}, "ds_opcoes2": {"nome": "Diretoria de Articulação Interfederativa (DAI)", "valor": "Diretoria de Articulação Interfederativa (DAI)"}, "ds_opcoes3": {"nome": "Diretoria de Avaliação, Monitoramento e Gestão da Informação (DAMGI)", "valor": "Diretoria de Avaliação, Monitoramento e Gestão da Informação (DAMGI)"}, "ds_opcoes4": {"nome": "Diretoria de Políticas para Povos e Comunidades Tradicionais de Matriz Africana e de Terreiros (DPMAT) / Diretoria de Políticas para Quilombolas e Ciganos (DQC)", "valor": "Diretoria de Políticas para Povos e Comunidades Tradicionais de Matriz Africana e de Terreiros (DPMAT) / Diretoria de Políticas para Quilombolas e Ciganos (DQC)"}, "ds_opcoes5": {"nome": "Assessoria Especial de Controle Interno (AECI)", "valor": "Assessoria Especial de Controle Interno (AECI)"}, "ds_opcoes6": {"nome": "Consultoria Jurídica (CONJUR)", "valor": "Consultoria Jurídica (CONJUR)"}, "ds_opcoes7": {"nome": "Assessoria Internacional (AI)", "valor": "Assessoria Internacional (AI)"}, "ds_opcoes8": {"nome": "Assessoria Especial de Assuntos Parlamentares (ASPAR)", "valor": "Assessoria Especial de Assuntos Parlamentares (ASPAR)"}, "ds_opcoes9": {"nome": "Diretoria de Ações Governamentais (DAG)", "valor": "Diretoria de Ações Governamentais (DAG)"}, "ds_opcoes10": {"nome": "Diretoria de Gestão e Administração (DGA), incluídas as unidades CGAL e DIGEP", "valor": "Diretoria de Gestão e Administração (DGA), incluídas as unidades CGAL e DIGEP"}, "ds_opcoes11": {"nome": "Assessoria Especial do Ministro (AEM)", "valor": "Assessoria Especial do Ministro (AEM)"}, "ds_opcoes12": {"nome": "Ouvidoria (OUV)", "valor": "Ouvidoria (OUV)"}, "ds_opcoes13": {"nome": "Gabinete do Ministro (GAB. MIN.)", "valor": "Gabinete do Ministro (GAB. MIN.)"}, "ds_opcoes14": {"nome": "Gabinete da Secretaria (GAB)", "valor": "Gabinete da Secretaria (GAB)"}, "ds_opcoes15": {"nome": "Assessoria Especial de Comunicação Social (ASCOM)", "valor": "Assessoria Especial de Comunicação Social (ASCOM)"}, "ds_opcoes16": {"nome": "Secretaria-Executiva (SE)", "valor": "Secretaria-Executiva (SE)"}, "ds_opcoes17": {"nome": "Corregedoria (CORREG)", "valor": "Corregedoria (CORREG)"}, "ds_opcoes18": {"nome": "fonte_dw", "valor": "pei_areas"}}', 'nao', 5, @ted_g_b3, 'adesao', NULL, NULL);
INSERT INTO `joom_tb_pergunta` (`state`, `ordering`, `created_by`, `modified_by`, `ds_titulo`, `co_edital`, `ds_descricao`, `tp_pergunta`, `ds_opcoes`, `tp_requerida`, `qt_dias_complementacao`, `co_agrupamento`, `tp_etapa`, `depende_de`, `depende_de_valor`)
VALUES (1, 12, 0, 0, 'Objetivos Estratégicos', @ted_edital, '', 'checkbox', '{"ds_opcoes0": {"nome": "Objetivo Estratégico 1 - Finalístico: garantir a criação de oportunidades para a inclusão de pessoas negras, na educação, no mercado de trabalho público e privado, e na política institucional, através da elaboração e acompanhamento das políticas de ações afirmativas intersetoriais", "valor": "Objetivo Estratégico 1 - Finalístico: garantir a criação de oportunidades para a inclusão de pessoas negras, na educação, no mercado de trabalho público e privado, e na política institucional, através da elaboração e acompanhamento das políticas de ações afirmativas intersetoriais"}, "ds_opcoes1": {"nome": "Objetivo Estratégico 2 - Finalístico: promover a igualdade de direitos para toda a população negra, em especial para a juventude negra, enfrentando e superando o racismo em todas as suas formas de expressão, através de políticas públicas intersetoriais e transversais", "valor": "Objetivo Estratégico 2 - Finalístico: promover a igualdade de direitos para toda a população negra, em especial para a juventude negra, enfrentando e superando o racismo em todas as suas formas de expressão, através de políticas públicas intersetoriais e transversais"}, "ds_opcoes2": {"nome": "Objetivo Estratégico 3 - Finalístico: promover estratégias e políticas transversais para a igualdade racial em todo o território nacional, articulando e apoiando órgãos municipais, estaduais e do distrito federal, por meio da reestruturação, ampliação, consolidação e aprofundamento do alcance do SINAPIR", "valor": "Objetivo Estratégico 3 - Finalístico: promover estratégias e políticas transversais para a igualdade racial em todo o território nacional, articulando e apoiando órgãos municipais, estaduais e do distrito federal, por meio da reestruturação, ampliação, consolidação e aprofundamento do alcance do SINAPIR"}, "ds_opcoes3": {"nome": "Objetivo Estratégico 4 - Finalístico: desenvolver e aperfeiçoar instrumentos de avaliação de políticas públicas, promovendo a produção, organização e divulgação de informações, dados e indicadores, por meio da qualificação da capacidade de formulação, execução, monitoramento e avaliação das políticas de igualdade racial", "valor": "Objetivo Estratégico 4 - Finalístico: desenvolver e aperfeiçoar instrumentos de avaliação de políticas públicas, promovendo a produção, organização e divulgação de informações, dados e indicadores, por meio da qualificação da capacidade de formulação, execução, monitoramento e avaliação das políticas de igualdade racial"}, "ds_opcoes4": {"nome": "Objetivo Estratégico 5 - Finalístico (DPMAT): assegurar direitos e superar o racismo religioso e a intolerância religiosa contra Povos e Comunidades Tradicionais de Matriz Africana e Povos de Terreiros, por meio de medidas intersetoriais de promoção da liberdade religiosa, respeito à ancestralidade, justiça social e climática, territorialidade e valorização do etnodesenvolvimento", "valor": "Objetivo Estratégico 5 - Finalístico (DPMAT): assegurar direitos e superar o racismo religioso e a intolerância religiosa contra Povos e Comunidades Tradicionais de Matriz Africana e Povos de Terreiros, por meio de medidas intersetoriais de promoção da liberdade religiosa, respeito à ancestralidade, justiça social e climática, territorialidade e valorização do etnodesenvolvimento"}, "ds_opcoes5": {"nome": "Objetivo Estratégico 6 - Finalístico (DQC): promover a melhoria da qualidade de vida, o bem viver, a paz e a justiça climática para comunidades quilombolas e povos ciganos, garantindo o acesso e a política de incentivo e proteção social, por meio do fortalecimento das estratégias de cuidado socioambiental das atuais e futuras gerações", "valor": "Objetivo Estratégico 6 - Finalístico (DQC): promover a melhoria da qualidade de vida, o bem viver, a paz e a justiça climática para comunidades quilombolas e povos ciganos, garantindo o acesso e a política de incentivo e proteção social, por meio do fortalecimento das estratégias de cuidado socioambiental das atuais e futuras gerações"}, "ds_opcoes6": {"nome": "fonte_dw", "valor": "pei_objetivos"}}', 'nao', 5, @ted_g_b3, 'adesao', NULL, NULL);
