VALUES (1, 1, 0, 0, 'Orientação - TEDs multi-objeto', @ted_ges_edital, '<p>Em TEDs multi-objeto, os beneficiários são informados por projeto/ação, e não somados no nível do TED, preservando a rastreabilidade de qual instituição beneficiou quais grupos, em que território e sobre qual tema.</p>', 'informativo', '{"ds_opcoes0": {"nome": "classe", "valor": "info"}}', 'nao', 5, @ted_ges_g_b5, 'adesao', NULL, NULL);
