VALUES (1, 2, 0, 0, 'Execução por organização parceira', @ted_ges_edital, '<h5 class="mt-3">Execução por organização parceira</h5>', 'informativo', NULL, 'nao', 5, @ted_ges_g_b5, 'adesao', NULL, NULL);
