VALUES (1, 3, 0, 0, 'Esta atividade é executada por uma organização parceira à sua?', @ted_ges_edital, 'Por exemplo, sua organização é responsável pela abertura de editais para selecionar organizações para executarem atividades específicas - cursos, oficinas, elaboração de materiais, etc.', 'radio', '{"ds_opcoes0": {"nome": "Sim, as atividades finalísticas do TED são executadas exclusivamente por organização parceira", "valor": "Sim, as atividades finalísticas do TED são executadas exclusivamente por organização parceira"}, "ds_opcoes1": {"nome": "Não, as atividades finalísticas do TED são executadas exclusivamente pela unidade descentralizada", "valor": "Não, as atividades finalísticas do TED são executadas exclusivamente pela unidade descentralizada"}, "ds_opcoes2": {"nome": "Ambos, as atividades finalísticas são executadas tanto por parceiros à organização quanto pela unidade finalística", "valor": "Ambos, as atividades finalísticas são executadas tanto por parceiros à organização quanto pela unidade finalística"}}', 'sim', 5, @ted_ges_g_b5, 'adesao', NULL, NULL);
