VALUES (1, 4, 0, 0, 'Projetos / ações apoiados e instituições executoras', @ted_ges_edital, 'Adicione um item por projeto/ação apoiada, com o responsável e o CPF dele: é com esse CPF que ele acessa a execução do projeto em "Meus instrumentos".', 'tabela', '{"ds_opcoes0": {"nome": "colunas", "valor": "[{\\"chave\\": \\"instituicao\\", \\"rotulo\\": \\"Instituição executora\\", \\"tipo\\": \\"linha\\", \\"obrigatoria\\": true}, {\\"chave\\": \\"cnpj\\", \\"rotulo\\": \\"CNPJ (quando se aplicar)\\", \\"tipo\\": \\"cnpj\\"}, {\\"chave\\": \\"tema\\", \\"rotulo\\": \\"Tema / objeto do projeto\\", \\"tipo\\": \\"linha\\", \\"obrigatoria\\": true}, {\\"chave\\": \\"posicao\\", \\"rotulo\\": \\"Posição na cadeia\\", \\"tipo\\": \\"lista\\", \\"obrigatoria\\": true, \\"opcoes\\": [\\"Repassador (2ª ponta)\\", \\"Executor direto (3ª ponta)\\", \\"Subexecutor / fundação de apoio (4ª ponta)\\"]}, {\\"chave\\": \\"valor\\", \\"rotulo\\": \\"Valor gasto (R$)\\", \\"tipo\\": \\"moeda\\"}, {\\"chave\\": \\"responsavel\\", \\"rotulo\\": \\"Responsável pelo projeto\\", \\"tipo\\": \\"linha\\", \\"obrigatoria\\": true}, {\\"chave\\": \\"cpf\\", \\"rotulo\\": \\"CPF do responsável\\", \\"tipo\\": \\"cpf\\", \\"obrigatoria\\": true}, {\\"chave\\": \\"email\\", \\"rotulo\\": \\"E-mail do responsável\\", \\"tipo\\": \\"linha\\", \\"obrigatoria\\": true}]"}, "ds_opcoes1": {"nome": "projetos_execucao", "valor": "execução pela própria Unidade Descentralizada"}, "ds_opcoes2": {"nome": "propria_quando", "valor": "[\\"Não, as atividades finalísticas do TED são executadas exclusivamente pela unidade descentralizada\\", \\"Ambos, as atividades finalísticas são executadas tanto por parceiros à organização quanto pela unidade finalística\\"]"}}', 'nao', 5, @ted_ges_g_b5, 'adesao', @ted_ges_p_parceira, '["Sim, as atividades finalísticas do TED são executadas exclusivamente por organização parceira", "Ambos, as atividades finalísticas são executadas tanto por parceiros à organização quanto pela unidade finalística"]');
INSERT INTO `joom_tb_pergunta` (`state`, `ordering`, `created_by`, `modified_by`, `ds_titulo`, `co_edital`, `ds_descricao`, `tp_pergunta`, `ds_opcoes`, `tp_requerida`, `qt_dias_complementacao`, `co_agrupamento`, `tp_etapa`, `depende_de`, `depende_de_valor`)
VALUES (1, 5, 0, 0, 'Execução dos projetos', @ted_ges_edital, '<p>Ao enviar este formulário, cada projeto da lista aparece em "Meus instrumentos" para o responsável, que entra com o CPF informado e preenche o formulário de execução: nele são registradas as atividades executadas no período e os beneficiários alcançados, uma atividade por preenchimento. Quando a própria Unidade Descentralizada executa atividades, o próprio gestor faz o registro, também em "Meus instrumentos".</p>', 'informativo', '{"ds_opcoes0": {"nome": "classe", "valor": "info"}}', 'nao', 5, @ted_ges_g_b5, 'adesao', NULL, NULL);

