INSERT INTO `joom_tb_edital` (`state`, `ordering`, `created_by`, `modified_by`, `no_edital`, `ds_edital`, `dt_abertura`, `dt_encerramento`, `dt_publicacao`, `tp_edital`, `co_edital_adesao`, `co_grupos`)
VALUES (1, 0, 0, 0, 'Coleta MIR - TEDs (execução)', '<p>Registro das atividades executadas e dos beneficiários alcançados nos Termos de Execução Descentralizada (TEDs) celebrados pelo MIR: um preenchimento por atividade.</p><p><strong>Quem preenche:</strong> o responsável por cada projeto, vinculado pelo CPF na lista de projetos do gestor do TED, ou o próprio gestor, quando a Unidade Descentralizada executa diretamente. O preenchimento começa pelo projeto, em "Meus instrumentos". O TED, o período e o projeto vêm definidos pelo gestor.</p>', '2026-11-01 00:00:00', '2027-12-31 23:59:59', '2026-11-01 00:00:00', 'formulario', @ted_ges_edital, NULL);
SET @ted_ex_edital = LAST_INSERT_ID();

