VALUES (1, 21, 0, 0, 'Povos e Comunidades Tradicionais e Grupos Específicos beneficiados', @ted_ex_edital, 'Seleção principal conforme os 16 GPTEs do Cadastro Único (MDS). Outros PCTs (Decreto nº 6.040/2007), quando não enquadrados acima: caiçaras, caboclos, catingueiros, faxinalenses, fundo e fecho de pasto, geraiszeiros, ilhéus, marroquianos, pantaneiros, pomeranos, retireiros do Araguaia, vazanteiros, veredeiros, benzedeiros, raizeiros. Use a opção "Outro" para informá-los.', 'checkbox', '{"ds_opcoes0": {"nome": "Grupos étnicos - Indígenas", "valor": "Grupos étnicos - Indígenas"}, "ds_opcoes1": {"nome": "Grupos étnicos - Quilombolas", "valor": "Grupos étnicos - Quilombolas"}, "ds_opcoes2": {"nome": "Grupos étnicos - Comunidades de terreiro / matriz africana", "valor": "Grupos étnicos - Comunidades de terreiro / matriz africana"}, "ds_opcoes3": {"nome": "Grupos étnicos - Ciganos", "valor": "Grupos étnicos - Ciganos"}, "ds_opcoes4": {"nome": "Meio ambiente - Extrativistas (quebradeiras de coco babaçu, catadores de mangaba, apanhadores de flores sempre-vivas, andirobeiros, cipozeiros, extrativistas costeiros e marinhos)", "valor": "Meio ambiente - Extrativistas (quebradeiras de coco babaçu, catadores de mangaba, apanhadores de flores sempre-vivas, andirobeiros, cipozeiros, extrativistas costeiros e marinhos)"}, "ds_opcoes5": {"nome": "Meio ambiente - Pescadores artesanais", "valor": "Meio ambiente - Pescadores artesanais"}, "ds_opcoes6": {"nome": "Meio ambiente - Ribeirinhos", "valor": "Meio ambiente - Ribeirinhos"}, "ds_opcoes7": {"nome": "Meio rural - Assentados da reforma agrária", "valor": "Meio rural - Assentados da reforma agrária"}, "ds_opcoes8": {"nome": "Meio rural - Acampados", "valor": "Meio rural - Acampados"}, "ds_opcoes9": {"nome": "Meio rural - Agricultores familiares", "valor": "Meio rural - Agricultores familiares"}, "ds_opcoes10": {"nome": "Meio rural - Beneficiários do Programa Nacional de Crédito Fundiário", "valor": "Meio rural - Beneficiários do Programa Nacional de Crédito Fundiário"}, "ds_opcoes11": {"nome": "Situações conjunturais - Atingidos por empreendimentos de infraestrutura", "valor": "Situações conjunturais - Atingidos por empreendimentos de infraestrutura"}, "ds_opcoes12": {"nome": "Situações conjunturais - Famílias de presos do sistema carcerário", "valor": "Situações conjunturais - Famílias de presos do sistema carcerário"}, "ds_opcoes13": {"nome": "Situações conjunturais - Catadores de material reciclável", "valor": "Situações conjunturais - Catadores de material reciclável"}, "ds_opcoes14": {"nome": "Situações conjunturais - Pessoas em situação de rua", "valor": "Situações conjunturais - Pessoas em situação de rua"}, "ds_opcoes15": {"nome": "Situações conjunturais - Desalojados ou desabrigados", "valor": "Situações conjunturais - Desalojados ou desabrigados"}, "ds_opcoes16": {"nome": "permite_outro", "valor": "sim"}}', 'nao', 5, @ted_ex_g_b5, 'adesao', NULL, NULL);
