-- ======================================================================
-- Coleta MIR - Convênios (MIR)
-- ======================================================================
INSERT INTO `joom_tb_edital` (`state`, `ordering`, `created_by`, `modified_by`, `no_edital`, `ds_edital`, `dt_abertura`, `dt_encerramento`, `dt_publicacao`, `tp_edital`, `co_edital_adesao`, `co_grupos`)
VALUES (1, 0, 0, 0, 'Coleta MIR - Convênios (MIR)', '<p>Instrumento para coleta de dados de forma territorializada dos convênios, contratos de repasse e termos de fomento e de colaboração celebrados pelo Ministério da Igualdade Racial (MIR), na qualidade de concedente.</p><p>O Coleta MIR não substitui o registro dos atos de execução, acompanhamento e fiscalização, nem a prestação de contas, exigidos no Transferegov.br (Decreto nº 11.531/2023); seu propósito é complementar esses registros com informações territorializadas.</p><p><strong>Perfis de preenchimento:</strong></p><ul><li><strong>Identificação, responsáveis, enquadramento, modalidade de resposta e fiscalização:</strong> servidor do MIR (concedente)</li><li><strong>Execução e projetos:</strong> convenente (atualização periódica), em formulário próprio (convenente), a partir do instrumento em "Meus instrumentos", com o acesso da sua CNPJ liberado pelo MIR</li><li><strong>Atividades e beneficiários:</strong> responsável por cada projeto, identificado pelo CPF na lista de projetos do convenente, em formulário próprio (execução), um preenchimento por atividade</li></ul><p>A sugestão de periodicidade de atualização é trimestral.</p><p>Campos marcados como automáticos serão preenchidos a partir do Transferegov.br / SIAFI / Siorg quando a integração estiver disponível; até lá, preencha manualmente.</p>', '2026-11-01 00:00:00', '2027-12-31 23:59:59', '2026-11-01 00:00:00', 'formulario', NULL, (SELECT GROUP_CONCAT(`id` ORDER BY `id`) FROM `joom_usergroups` WHERE `title` IN ('Gerenciar Adesões')));
SET @conv_edital = LAST_INSERT_ID();

