VALUES (1, 12, 0, 0, 'Objetivos Estratégicos', @conv_edital, '', 'checkbox', '{"ds_opcoes0": {"nome": "Objetivo Estratégico 1 - Finalístico: garantir a criação de oportunidades para a inclusão de pessoas negras, na educação, no mercado de trabalho público e privado, e na política institucional, através da elaboração e acompanhamento das políticas de ações afirmativas intersetoriais", "valor": "Objetivo Estratégico 1 - Finalístico: garantir a criação de oportunidades para a inclusão de pessoas negras, na educação, no mercado de trabalho público e privado, e na política institucional, através da elaboração e acompanhamento das políticas de ações afirmativas intersetoriais"}, "ds_opcoes1": {"nome": "Objetivo Estratégico 2 - Finalístico: promover a igualdade de direitos para toda a população negra, em especial para a juventude negra, enfrentando e superando o racismo em todas as suas formas de expressão, através de políticas públicas intersetoriais e transversais", "valor": "Objetivo Estratégico 2 - Finalístico: promover a igualdade de direitos para toda a população negra, em especial para a juventude negra, enfrentando e superando o racismo em todas as suas formas de expressão, através de políticas públicas intersetoriais e transversais"}, "ds_opcoes2": {"nome": "Objetivo Estratégico 3 - Finalístico: promover estratégias e políticas transversais para a igualdade racial em todo o território nacional, articulando e apoiando órgãos municipais, estaduais e do distrito federal, por meio da reestruturação, ampliação, consolidação e aprofundamento do alcance do SINAPIR", "valor": "Objetivo Estratégico 3 - Finalístico: promover estratégias e políticas transversais para a igualdade racial em todo o território nacional, articulando e apoiando órgãos municipais, estaduais e do distrito federal, por meio da reestruturação, ampliação, consolidação e aprofundamento do alcance do SINAPIR"}, "ds_opcoes3": {"nome": "Objetivo Estratégico 4 - Finalístico: desenvolver e aperfeiçoar instrumentos de avaliação de políticas públicas, promovendo a produção, organização e divulgação de informações, dados e indicadores, por meio da qualificação da capacidade de formulação, execução, monitoramento e avaliação das políticas de igualdade racial", "valor": "Objetivo Estratégico 4 - Finalístico: desenvolver e aperfeiçoar instrumentos de avaliação de políticas públicas, promovendo a produção, organização e divulgação de informações, dados e indicadores, por meio da qualificação da capacidade de formulação, execução, monitoramento e avaliação das políticas de igualdade racial"}, "ds_opcoes4": {"nome": "Objetivo Estratégico 5 - Finalístico (DPMAT): assegurar direitos e superar o racismo religioso e a intolerância religiosa contra Povos e Comunidades Tradicionais de Matriz Africana e Povos de Terreiros, por meio de medidas intersetoriais de promoção da liberdade religiosa, respeito à ancestralidade, justiça social e climática, territorialidade e valorização do etnodesenvolvimento", "valor": "Objetivo Estratégico 5 - Finalístico (DPMAT): assegurar direitos e superar o racismo religioso e a intolerância religiosa contra Povos e Comunidades Tradicionais de Matriz Africana e Povos de Terreiros, por meio de medidas intersetoriais de promoção da liberdade religiosa, respeito à ancestralidade, justiça social e climática, territorialidade e valorização do etnodesenvolvimento"}, "ds_opcoes5": {"nome": "Objetivo Estratégico 6 - Finalístico (DQC): promover a melhoria da qualidade de vida, o bem viver, a paz e a justiça climática para comunidades quilombolas e povos ciganos, garantindo o acesso e a política de incentivo e proteção social, por meio do fortalecimento das estratégias de cuidado socioambiental das atuais e futuras gerações", "valor": "Objetivo Estratégico 6 - Finalístico (DQC): promover a melhoria da qualidade de vida, o bem viver, a paz e a justiça climática para comunidades quilombolas e povos ciganos, garantindo o acesso e a política de incentivo e proteção social, por meio do fortalecimento das estratégias de cuidado socioambiental das atuais e futuras gerações"}, "ds_opcoes6": {"nome": "fonte_dw", "valor": "pei_objetivos"}}', 'nao', 5, @conv_g_b3, 'adesao', NULL, NULL);
