INSERT INTO `joom_tb_edital` (`state`, `ordering`, `created_by`, `modified_by`, `no_edital`, `ds_edital`, `dt_abertura`, `dt_encerramento`, `dt_publicacao`, `tp_edital`, `co_edital_adesao`, `co_grupos`)
VALUES (1, 0, 0, 0, 'Coleta MIR - Convênios (convenente)', '<p>Atualização periódica da execução dos convênios celebrados pelo MIR, na qualidade de concedente.</p><p><strong>Quem preenche:</strong> convenente: forma de execução, contrapartida, bens e os projetos/ações apoiados, com seus responsáveis. Identificação, responsáveis, enquadramento e fiscalização são preenchidos pelo servidor do MIR em formulário próprio.</p><p>Ao enviar, cada projeto aparece em "Meus instrumentos" para o responsável informado (pelo CPF), que registra no formulário de execução as atividades e os beneficiários.</p><p>A sugestão de periodicidade de atualização é trimestral.</p>', '2026-11-01 00:00:00', '2027-12-31 23:59:59', '2026-11-01 00:00:00', 'formulario', NULL, NULL);
SET @conv_ges_edital = LAST_INSERT_ID();

