VALUES (1, 1, 0, 0, 'Orientação - convênios com mais de uma meta', @conv_ges_edital, '<p>Em convênios com mais de uma meta, ação ou executor, os beneficiários são informados por meta/ação, e não somados no nível do convênio, preservando a rastreabilidade de qual instituição beneficiou quais grupos, em que território e sobre qual tema.</p>', 'informativo', '{"ds_opcoes0": {"nome": "classe", "valor": "info"}}', 'nao', 5, @conv_ges_g_b5, 'adesao', NULL, NULL);
