VALUES (1, 2, 0, 0, 'Execução por organização distinta do convenente', @conv_ges_edital, '<h5 class="mt-3">Execução por organização distinta do convenente</h5>', 'informativo', NULL, 'nao', 5, @conv_ges_g_b5, 'adesao', NULL, NULL);
