VALUES (1, 3, 0, 0, 'Esta atividade é executada por organização distinta do convenente?', @conv_ges_edital, 'Por exemplo: o convenente contrata empresa, seleciona organizações por chamada pública ou repassa recursos a outra instituição para executar cursos, oficinas, obras, elaboração de materiais, etc.', 'radio', '{"ds_opcoes0": {"nome": "Sim, as atividades finalísticas do convênio são executadas exclusivamente por terceiros (interveniente, contratado ou parceiro)", "valor": "Sim, as atividades finalísticas do convênio são executadas exclusivamente por terceiros (interveniente, contratado ou parceiro)"}, "ds_opcoes1": {"nome": "Não, as atividades finalísticas do convênio são executadas exclusivamente pelo convenente", "valor": "Não, as atividades finalísticas do convênio são executadas exclusivamente pelo convenente"}, "ds_opcoes2": {"nome": "Ambos, as atividades finalísticas são executadas tanto pelo convenente quanto por terceiros", "valor": "Ambos, as atividades finalísticas são executadas tanto pelo convenente quanto por terceiros"}}', 'sim', 5, @conv_ges_g_b5, 'adesao', NULL, NULL);
