VALUES (1, 0, 0, 0, 'Coleta MIR - Convênios (execução)', '<p>Registro das atividades executadas e dos beneficiários alcançados nos convênios celebrados pelo MIR: um preenchimento por atividade.</p><p><strong>Quem preenche:</strong> o responsável por cada projeto, vinculado pelo CPF na lista de projetos do convenente, ou o próprio convenente, quando executa diretamente. O preenchimento começa pelo projeto, em "Meus instrumentos". O convênio, o período e o projeto vêm definidos pelo convenente.</p>', '2026-11-01 00:00:00', '2027-12-31 23:59:59', '2026-11-01 00:00:00', 'formulario', @conv_ges_edital, NULL);
SET @conv_ex_edital = LAST_INSERT_ID();

